int solution(int T, int N, int L, int arrive[], int arrive_len) {
    int answer = 0;  // 돌아간 손님 수
    int stock = 0;   // 통 안 팝콘 수
    int next = T;    // 다음에 팝콘을 튀기는 시각
    for (int i = 0; i < arrive_len; i++) {
        while (next <= arrive[i]) {  // 손님이 오기 전(같은 시각 포함)에 튀긴 팝콘을 담음
            stock += N;
            if (stock > L)
                stock = L;           // 통이 가득 차면 나머지는 버림
            next += T;
        }
        if (stock == 0)
            answer++;                // 통이 비었으면 이 손님만 돌아감
        else
            stock--;
    }
    return answer;
}

