#include <stdlib.h>

int* solution(int a, int b, int arrive[], int arrive_len, int flavor[], int flavor_len) {
    int* answer = (int*)malloc(sizeof(int) * 2);
    int used[2] = {0, 0};  // 맛별로 팔린 컵 수(0: 딸기, 1: 초코)
    int changed = 0;       // 바꿔 산 손님 수
    int gone = 0;          // 돌아간 손님 수
    for (int i = 0; i < arrive_len; i++) {
        int left[2];
        left[0] = arrive[i] / a - used[0];  // 지금 남은 딸기 맛
        left[1] = arrive[i] / b - used[1];  // 지금 남은 초코 맛
        int want = flavor[i];
        int other = 1 - want;
        if (left[want] > 0) {
            used[want]++;
        } else if (left[other] > 0) {
            used[other]++;
            changed++;
        } else {
            gone++;
        }
    }
    answer[0] = changed;
    answer[1] = gone;
    return answer;
}

