int* solution(int T, int N, int arrive[], int arrive_len) {
    int* answer = (int*)malloc(sizeof(int) * 2);
    int total = 0;    // 기다린 시간의 합
    int longest = 0;  // 가장 오래 기다린 시간
    for (int i = 0; i < arrive_len; i++) {
        int wait = ready_time(i, T, N) - arrive[i];  // i번째 손님은 i번째 붕어빵을 받음
        if (wait < 0)
            wait = 0;                                // 이미 나와 있으면 바로 삼
        total += wait;
        if (wait > longest)
            longest = wait;
    }
    answer[0] = total;
    answer[1] = longest;
    return answer;
}

