#include <stdlib.h>

int ready_time(int k, int T, int N) {
    return (k / N + 1) * T;  // 0부터 센 k번째 타코야끼가 나오는 시각
}

int* solution(int T, int N, int W, int arrive[], int arrive_len) {
    int* answer = (int*)malloc(sizeof(int) * 2);
    int got = 0;    // 줄을 서서 받은 손님 수 = 다음 손님이 받을 타코야끼 번호
    int gone = 0;   // 돌아간 손님 수
    int last = -1;  // 마지막으로 받은 시각(아무도 받지 않으면 -1)
    for (int i = 0; i < arrive_len; i++) {
        int serve = ready_time(got, T, N);  // 줄을 서면 받게 되는 시각
        if (serve < arrive[i])
            serve = arrive[i];              // 이미 나와 남아 있으면 바로 받음
        if (serve - arrive[i] > W) {
            gone++;                         // W초보다 오래 기다려야 하면 돌아감
        } else {
            got++;
            last = serve;
        }
    }
    answer[0] = gone;
    answer[1] = last;
    return answer;
}

