#include <stdlib.h>

int* solution(int T, int N, int K, int arrive[], int arrive_len) {
    int* answer = (int*)malloc(sizeof(int) * 2);
    int cnt[1001];   // cnt[b]: b번째 판(b * T초에 구움)에 남은 크루아상 수
    int made = 0;    // 지금까지 구운 판 수
    int old = 1;     // 아직 치우지 않은 가장 오래된 판 번호
    int gone = 0;    // 돌아간 손님 수
    int thrown = 0;  // 버린 크루아상 수
    for (int i = 0; i < arrive_len; i++) {
        int t = arrive[i];
        while ((made + 1) * T <= t) {  // t초까지(같은 시각 포함) 구운 판을 올림
            made++;
            cnt[made] = N;
        }
        while (old <= made && (cnt[old] == 0 || old * T + K <= t)) {
            thrown += cnt[old];        // 다 팔린 판은 0개, 기한이 지난 판은 남은 만큼 버림
            old++;
        }
        if (old <= made)
            cnt[old]--;                // 가장 먼저 구운 판에서 1개를 삼
        else
            gone++;
    }
    answer[0] = gone;
    answer[1] = thrown;
    return answer;
}

